changeSet.sql:
ALTER TABLE hive_collectors ENABLE ROW LEVEL SECURITY;
ALTER TABLE hive_collectors FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hive_collectors
    USING (tenant_id = COALESCE(NULLIF(current_setting('app.current_tenant', true), '')::bigint, -1))
    WITH CHECK (tenant_id = COALESCE(NULLIF(current_setting('app.current_tenant', true), '')::bigint, -1));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON hive_collectors;
ALTER TABLE hive_collectors NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hive_collectors DISABLE ROW LEVEL SECURITY;

